#include <limits>
#include <iostream>

int main() {
    // Integer bounds
    std::cout << "Int Max: " << std::numeric_limits<int>::max() << "\n";
    std::cout << "Int Min: " << std::numeric_limits<int>::min() << "\n";

    // Floating point bounds (min is smallest positive normalized)
    std::cout << "Float Max: " << std::numeric_limits<float>::max() << "\n";
    std::cout << "Float Min (Smallest Positive): " 
              << std::numeric_limits<float>::min() << "\n";

    // Note: The most negative float value is generally -max()
}
